	"fetched_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "shipping_rate_cache_lookup_key" UNIQUE("origin_id","destination_id","weight_grams","services_key"),
	CONSTRAINT "shipping_rate_cache_weight_grams_check" CHECK ("shipping_rate_cache"."weight_grams" > 0)
);
